const doctor={id:'UTM-0001',name:'Dr. Alejandro Toledo'};
const procedure='PR-0048';
const patients=['Paciente A-104','Paciente A-205','Paciente A-318'];
const services=['Cirugía ambulatoria','Hospitalización','Procedimiento diagnóstico'];
const names=['Recepción','Admisiones','Vínculo','Atención','Cuentas','Resultado'];
let state=Program.read();
const screen=document.querySelector('#screen');
const save=()=>Program.write(state);
const date=()=>Program.today();
const suffix=()=>`?cierre=1&fecha=${state.closedAt||date()}`;
const page=(name,closed=false)=>`${name}.html${closed?suffix():''}`;
const badge=(label,kind='')=>`<span class="status ${kind}">${label}</span>`;
const summary=()=>`<div class="summary"><div class="summary-row"><span>Paciente</span><strong>${state.patient}</strong></div><div class="summary-row"><span>Servicio</span><strong>${state.service}</strong></div><div class="summary-row"><span>Tipo</span><strong>Procedimiento ${state.mode==='privado'?'privado':'interno'}</strong></div><div class="summary-row"><span>Médico del programa</span><strong>${state.mode==='privado'?doctor.name:'Sin asignar'}</strong></div><div class="summary-row"><span>Procedimiento</span><strong>${procedure}</strong></div></div>`;
const insight=(count,label)=>`<div class="insight"><div><span>${label}</span><strong>${doctor.name}</strong></div><div class="count">${count}<small> / 12</small></div></div>`;
const frame=(area,title,lead,body)=>`<article class="screen-card"><div class="topline"><span class="eyebrow">${area}</span><span class="serial">${state.stage<2?'REGISTRO':procedure}</span></div><h2>${title}</h2><p class="lead">${lead}</p>${body}</article>`;
const select=(id,label,choices,value)=>`<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${id}">${choices.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></div>`;
const modeField=()=>`${select('mode','Tipo de procedimiento',[['privado','Procedimiento privado'],['interno','Procedimiento interno']],state.mode)}<div class="field wide" id="private-fields" ${state.mode==='interno'?'hidden':''}><label for="barcode">Código de barras de la tarjeta médica</label><div class="scan-row"><input id="barcode" name="barcode" type="text" autocomplete="off" inputmode="text" placeholder="Escanear o escribir código" value="${state.doctor}"><button type="button" class="secondary" id="sample-scan">Escanear tarjeta</button></div><p id="scan-result" class="field-hint">${state.doctor?`${doctor.name} · ${doctor.id}`:'El código identifica al médico del programa.'}</p><div class="doctor-found"><span>Médico identificado</span><strong id="doctor-name">${state.doctor?doctor.name:''}</strong></div><a class="help-link" href="tarjeta.html" target="_blank" rel="noopener">Ver tarjeta médica ↗</a></div><div class="field wide" id="internal-note" ${state.mode==='privado'?'hidden':''}><div class="muted-panel"><strong>Procedimiento interno</strong><p>El médico del programa permanece vacío.</p></div></div>`;
function form(kind){const reception=kind==='reception';return `<form id="entry"><div class="his-form"><section class="his-panel"><h3>${reception?'Paciente nuevo':'Paciente y atención'}</h3><div class="form-grid">${select('patient','Paciente',patients.map(x=>[x,x]),state.patient)}${reception?`<div class="field"><label>Tipo de registro</label><input value="Paciente nuevo" disabled></div>`:select('service','Servicio',services.map(x=>[x,x]),state.service)}${modeField()}</div></section><section class="his-panel"><h3>${reception?'Registro inicial':'Datos para Cuentas'}</h3><p class="field-hint">${reception?'Recepción registra al paciente y conserva el tipo de procedimiento.':'El vínculo queda asociado al procedimiento antes de la atención.'}</p><div class="form-grid"><div class="field"><label>${reception?'Código de paciente':'Sede'}</label><input value="${reception?state.patient:'Consulta externa'}" disabled></div><div class="field"><label>${reception?'Estado':'Flujo administrativo'}</label><input value="${reception?'Por admitir':'Cuenta y FEL'}" disabled></div></div></section></div><p id="form-error" class="form-error" role="alert"></p><div class="actions"><button type="submit" class="primary">${reception?'Guardar paciente y abrir Admisiones':'Crear admisión y vincular médico'} →</button></div></form>`;}
function renderSteps(){const el=document.querySelector('#steps');el.className='steps';el.innerHTML=names.map((n,i)=>`<div class="step ${state.stage>i?'passed':state.stage===i?'current':''}"><span class="step-dot">${state.stage>i?'✓':i+1}</span><div class="step-text"><strong>${n}</strong><small>${state.stage>i?'Completado':state.stage===i?'En curso':'Pendiente'}</small></div></div>`).join('')+`<div class="mobile-steps" aria-hidden="true">${names.map((_,i)=>`<span class="${state.stage>=i?'active':''}"></span>`).join('')}</div>`;document.querySelector('#reset').hidden=state.stage===0;}
function render(){renderSteps();let body='';
 if(state.stage===0)body=frame('RECEPCIÓN','Registrar paciente nuevo','Selecciona el tipo de procedimiento. Si es privado, la tarjeta permite identificar al médico.',form('reception'));
 if(state.stage===1)body=frame('ADMISIONES','Nueva admisión','Confirma el servicio, el tipo de procedimiento y la identificación del médico.',form('admission'));
 if(state.stage===2)body=frame('ADMISIÓN REGISTRADA','Vínculo guardado','El procedimiento quedó registrado para continuar a Atención.',`${badge(state.mode==='privado'?'Médico vinculado':'Sin médico del programa','good')}${summary()}${state.mode==='privado'?insight(11,'AVANCE ANTES DEL CIERRE'):''}<div class="actions"><button class="primary" data-next="3">Continuar a Atención →</button><button class="secondary" data-next="1">Editar admisión</button></div>`);
 if(state.stage===3)body=frame('ATENCIÓN','Procedimiento realizado','El procedimiento está listo para Cuentas.',`${badge('Atención registrada','good')}${summary()}${state.mode==='privado'?insight(11,'AVANCE SIN CAMBIOS'):''}<div class="actions"><button class="primary" data-next="4">Continuar a Cuentas →</button></div>`);
 if(state.stage===4)body=frame('CUENTAS','Conclusión del caso','La confirmación final de Cuentas acredita automáticamente el procedimiento.',`${summary()}${state.mode==='privado'?insight(11,'ANTES DE LA CONFIRMACIÓN'):''}<div class="actions"><button class="primary" data-next="5">Confirmar cierre de cuenta →</button>${state.mode==='privado'?`<a class="secondary" href="portal.html" target="_blank" rel="noopener">Ver portal antes del cierre</a>`:''}</div>`);
 if(state.stage===5)body=state.mode==='privado'?frame('CUENTA CERRADA','Procedimiento confirmado','Cuentas terminó el caso y registró un procedimiento una sola vez.',`${badge('Procedimiento acreditado','good')}${summary()}${insight(12,'CICLO BRONCE COMPLETADO')}<div class="result"><strong>Bronce → Silver</strong><p>El ciclo Bronce llegó a 12 de 12. El ciclo Silver inicia en 0 de 12 y se habilita el premio de categoría.</p></div><div class="actions"><a class="primary" href="${page('portal',true)}">Abrir portal del médico →</a><a class="secondary" href="${page('tarjeta',true)}">Ver tarjeta y QR →</a></div>`):frame('CUENTA CERRADA','Procedimiento interno concluido','No se acreditó avance a un médico del programa.',`${summary()}<div class="actions"><button class="primary" data-reset>Reiniciar recorrido</button></div>`);
 screen.innerHTML=body;
}
function advance(n){if(n===5&&state.stage===4){state.closedAt=date();state.stage=5;}else if(n===state.stage+1||n===1&&state.stage===2){state.stage=n;}else return;save();render();scrollTo(0,0);screen.focus({preventScroll:true});}
function reset(){state=Program.initial();save();render();scrollTo(0,0);}
function setDoctor(value){state.doctor=value.trim().toUpperCase()===doctor.id?doctor.id:'';const n=document.querySelector('#doctor-name'),r=document.querySelector('#scan-result');if(n)n.textContent=state.doctor?doctor.name:'';if(r)r.textContent=state.doctor?`${doctor.name} · ${doctor.id}`:'Código no encontrado';save();}
document.addEventListener('change',e=>{if(e.target.id==='mode'){state.mode=e.target.value;state.doctor='';save();render();}if(['patient','service'].includes(e.target.id)){state[e.target.id]=e.target.value;save();}});
document.addEventListener('input',e=>{if(e.target.id==='barcode')setDoctor(e.target.value);});
document.addEventListener('submit',e=>{if(e.target.id!=='entry')return;e.preventDefault();const f=new FormData(e.target);state.patient=f.get('patient');state.mode=f.get('mode');if(f.get('service'))state.service=f.get('service');if(state.mode==='privado'&&state.doctor!==doctor.id){document.querySelector('#form-error').textContent='Escanea la tarjeta médica antes de continuar.';return;}advance(state.stage+1);});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='sample-scan'){document.querySelector('#barcode').value=doctor.id;setDoctor(doctor.id);}if(b.id==='reset'||b.hasAttribute('data-reset'))reset();if(b.dataset.next)advance(Number(b.dataset.next));});
window.addEventListener('storage',e=>{if(e.key===Program.key){state=Program.read();render();}});
render();
